// RelayServiceHandler is an implementation of the tooling.relay.v1.RelayService service.
type RelayServiceHandler interface {
	// Devices -- always answered from THIS instance's own local hardware, never aggregated
	// server-side (the caller aggregates across instances).
	ListDevices(context.Context, *connect.Request[v1.ListDevicesRequest]) (*connect.Response[v1.ListDevicesResponse], error)
	// Library
	ListTracks(context.Context, *connect.Request[v1.ListTracksRequest]) (*connect.Response[v1.ListTracksResponse], error)
	AddTrack(context.Context, *connect.Request[v1.AddTrackRequest]) (*connect.Response[v1.Track], error)
	UploadTrack(context.Context, *connect.ClientStream[v1.UploadTrackChunk]) (*connect.Response[v1.Track], error)
	RescanLibrary(context.Context, *connect.Request[v1.RescanLibraryRequest]) (*connect.Response[v1.RescanLibraryResponse], error)
	// Removes a track's row and its backing audio file from local disk. If the track is a
	// recording's finalized output (Track.recording_id set), the Recording row itself and its
	// transcript are untouched -- that's DeleteRecording's own, separate job (Archive, below); this
	// only ever removes the playable library entry.
	DeleteTrack(context.Context, *connect.Request[v1.DeleteTrackRequest]) (*connect.Response[v1.DeleteTrackResponse], error)
	// Playback -- Play/Pause/Seek/SetVolume target a specific output device, so they're always
	// called on the instance that owns it.
	Play(context.Context, *connect.Request[v1.PlayRequest]) (*connect.Response[v1.PlayerState], error)
	Pause(context.Context, *connect.Request[v1.PauseRequest]) (*connect.Response[v1.PlayerState], error)
	Seek(context.Context, *connect.Request[v1.SeekRequest]) (*connect.Response[v1.PlayerState], error)
	SetVolume(context.Context, *connect.Request[v1.SetVolumeRequest]) (*connect.Response[v1.PlayerState], error)
	GetPlayerState(context.Context, *connect.Request[v1.GetPlayerStateRequest]) (*connect.Response[v1.PlayerState], error)
	StreamAudioOut(context.Context, *connect.Request[v1.StreamAudioOutRequest], *connect.ServerStream[v1.AudioChunk]) error
	// Queue
	Enqueue(context.Context, *connect.Request[v1.EnqueueRequest]) (*connect.Response[v1.QueueState], error)
	ClearQueue(context.Context, *connect.Request[v1.ClearQueueRequest]) (*connect.Response[v1.QueueState], error)
	// Recording -- always called on the instance owning the input device, same reasoning as
	// Playback. StreamAudioIn is how a *real* gRPC client-streaming caller (a native capture pump,
	// not a browser) gets bytes to that instance; StreamAudioInChunk (added in Phase 10) is what
	// the Dioxus web client actually uses -- see its own doc for why.
	StartRecording(context.Context, *connect.Request[v1.StartRecordingRequest]) (*connect.Response[v1.Recording], error)
	StreamAudioIn(context.Context, *connect.ClientStream[v1.AudioChunk]) (*connect.Response[v1.StreamAudioInResponse], error)
	// StreamAudioInChunk is a Phase 10 addition: grpc-web from a browser cannot truly stream a
	// client-streaming request incrementally -- confirmed by reading tonic-web-wasm-client's own
	// source (its `prepare_body` collects the *entire* request into one `fetch()` call before
	// sending anything), so a live, open-ended microphone recording sent via StreamAudioIn would
	// never reach the server until the browser closed the connection, breaking live transcription
	// entirely. The web client instead calls this unary RPC once per captured buffer; it reuses
	// the exact same ingestion path (RecordingSession.Ingest) StreamAudioIn's own receive loop
	// does, just one chunk per call instead of one call for the whole stream.
	StreamAudioInChunk(context.Context, *connect.Request[v1.AudioChunk]) (*connect.Response[v1.StreamAudioInChunkResponse], error)
	AddMarker(context.Context, *connect.Request[v1.AddMarkerRequest]) (*connect.Response[v1.Marker], error)
	StopRecording(context.Context, *connect.Request[v1.StopRecordingRequest]) (*connect.Response[v1.Recording], error)
	DiscardRecording(context.Context, *connect.Request[v1.DiscardRecordingRequest]) (*connect.Response[v1.DiscardRecordingResponse], error)
	// Live transcript -- the Record page's own streaming captions. A dedicated RPC, not a
	// Catalyst Consume subscription -- same reasoning as Lineman's Watch.
	WatchTranscript(context.Context, *connect.Request[v1.WatchTranscriptRequest], *connect.ServerStream[v1.TranscriptSegment]) error
	// Archive
	ListRecordings(context.Context, *connect.Request[v1.ListRecordingsRequest]) (*connect.Response[v1.ListRecordingsResponse], error)
	GetRecording(context.Context, *connect.Request[v1.GetRecordingRequest]) (*connect.Response[v1.Recording], error)
	GetTranscript(context.Context, *connect.Request[v1.GetTranscriptRequest]) (*connect.Response[v1.GetTranscriptResponse], error)
	SearchTranscripts(context.Context, *connect.Request[v1.SearchTranscriptsRequest]) (*connect.Response[v1.SearchTranscriptsResponse], error)
	RenameSpeaker(context.Context, *connect.Request[v1.RenameSpeakerRequest]) (*connect.Response[v1.Speaker], error)
	DeleteRecording(context.Context, *connect.Request[v1.DeleteRecordingRequest]) (*connect.Response[v1.DeleteRecordingResponse], error)
	// Action items
	CreateActionItem(context.Context, *connect.Request[v1.CreateActionItemRequest]) (*connect.Response[v1.ActionItem], error)
	ListActionItems(context.Context, *connect.Request[v1.ListActionItemsRequest]) (*connect.Response[v1.ListActionItemsResponse], error)
	CreateLinemanTasks(context.Context, *connect.Request[v1.CreateLinemanTasksRequest]) (*connect.Response[v1.CreateLinemanTasksResponse], error)
}

